public boolean reserve(String sku) {
    int stock = repo.getStock(sku);        // SELECT stock FROM inventory WHERE sku = ?
    if (stock > 0) {
        repo.setStock(sku, stock - 1);     // UPDATE inventory SET stock = ? WHERE sku = ?
        return true;
    }
    return false;
}

