def get_product(pid):
    v = redis.get(f"p:{pid}")
    if v:
        return json.loads(v)
    row = db.query("SELECT * FROM products WHERE id = %s", pid)   # truy vấn nặng
    redis.set(f"p:{pid}", json.dumps(row), ex=60)
    return row

